export type LanguagePreference = 'en' | 'ms';
export const DEFAULT_LANGUAGE: LanguagePreference = 'en';
export const LANGUAGE_OPTIONS = [{ id: 'en', label: 'English' }, { id: 'ms', label: 'Bahasa Melayu' }] as const;

export function normalizeLanguagePreference(value: unknown): LanguagePreference {
  return value === 'ms' ? 'ms' : 'en';
}

